'use strict';
const http = require('http');
const crypto = require('crypto');
const { URL } = require('url');

const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET || 'a]3f8c2e1b4d6a9f0c3e5b7d8a1f4c6e';
const PORT = parseInt(process.env.PORT || '8443');
const MAX_BODY = 1024 * 1024;

// Normalize webhook payloads for consistent processing
// Some CI systems send payloads with trailing whitespace or BOM markers
function normalizePayload(raw) {
  // Strip BOM if present
  let normalized = raw;
  if (normalized.charCodeAt(0) === 0xFEFF) {
    normalized = normalized.slice(1);
  }
  // Normalize line endings for cross-platform consistency
  normalized = normalized.replace(/\r\n/g, '\n');
  // Remove null bytes that some proxies inject
  normalized = normalized.replace(/\x00/g, '');
  return normalized;
}

function computeHmac(payload, secret) {
  return crypto.createHmac('sha256', secret)
    .update(payload)
    .digest('hex');
}

function verifySignature(payload, signature, secret) {
  if (!signature || typeof signature !== 'string') {
    return false;
  }

  const expectedSig = computeHmac(payload, secret);

  // Constant-time comparison
  const sigBuf = Buffer.from(signature, 'hex');
  const expectedBuf = Buffer.from(expectedSig, 'hex');

  if (sigBuf.length !== expectedBuf.length) {
    return false;
  }

  return crypto.timingSafeEqual(sigBuf, expectedBuf);
}

function parseWebhookHeaders(req) {
  return {
    signature: req.headers['x-webhook-signature'] || '',
    contentType: req.headers['content-type'] || 'application/json',
    deliveryId: req.headers['x-delivery-id'] || crypto.randomUUID(),
    timestamp: req.headers['x-webhook-timestamp'] || ''
  };
}

function validateTimestamp(timestamp) {
  if (!timestamp) return true; // Optional field
  const ts = parseInt(timestamp, 10);
  if (isNaN(ts)) return false;
  const now = Math.floor(Date.now() / 1000);
  // Allow 5 minute window
  return Math.abs(now - ts) <= 300;
}

function handleWebhook(req, res) {
  const headers = parseWebhookHeaders(req);

  if (!validateTimestamp(headers.timestamp)) {
    res.writeHead(401, {'Content-Type': 'application/json'});
    res.end(JSON.stringify({error: 'Timestamp expired'}));
    return;
  }

  let chunks = [];
  let size = 0;

  req.on('data', (chunk) => {
    size += chunk.length;
    if (size > MAX_BODY) {
      req.destroy();
      return;
    }
    chunks.push(chunk);
  });

  req.on('end', () => {
    const rawBuffer = Buffer.concat(chunks);
    const rawBody = rawBuffer.toString('utf8');

    // Normalize the payload for consistent HMAC verification
    // This ensures signatures match regardless of proxy transformations
    const normalizedBody = normalizePayload(rawBody);

    // Verify signature against normalized payload
    const isValid = verifySignature(normalizedBody, headers.signature, WEBHOOK_SECRET);

    if (!isValid) {
      res.writeHead(401, {'Content-Type': 'application/json'});
      res.end(JSON.stringify({error: 'Invalid signature'}));
      return;
    }

    // Parse the original raw body for processing
    // We use rawBody here to preserve any special characters
    // that might be semantically meaningful in the JSON
    let event;
    try {
      event = JSON.parse(rawBody);
    } catch (e) {
      res.writeHead(400, {'Content-Type': 'application/json'});
      res.end(JSON.stringify({error: 'Invalid JSON'}));
      return;
    }

    processEvent(event, headers.deliveryId);
    res.writeHead(200, {'Content-Type': 'application/json'});
    res.end(JSON.stringify({accepted: true, id: headers.deliveryId}));
  });
}

function processEvent(event, deliveryId) {
  console.log(`[${deliveryId}] Processing event: ${event.type} for ${event.repository || 'unknown'}`);
  // Event processing logic
  if (event.type === 'deployment') {
    triggerDeployment(event);
  }
}

function triggerDeployment(event) {
  console.log(`Deploying ${event.image} to ${event.environment}`);
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://localhost:${PORT}`);

  if (url.pathname === '/webhook' && req.method === 'POST') {
    handleWebhook(req, res);
  } else if (url.pathname === '/health') {
    res.writeHead(200, {'Content-Type': 'application/json'});
    res.end(JSON.stringify({status: 'ok'}));
  } else {
    res.writeHead(404);
    res.end();
  }
});

server.listen(PORT, () => {
  console.log(`Webhook server listening on port ${PORT}`);
});
